/**
 * Returns
 *   - `1` if the character is a lower case letter,
 *   - `2` if the character is an upper case letter,
 *   - `3` if the character is a letter but not a lower or upper case letter,
 *   - `0` otherwise.
 */
internal actual fun getLetterType(code: Int): Int {
    val index = binarySearchRange(Letter.decodedRangeStart, code)

    val rangeStart = Letter.decodedRangeStart[index]
    val rangeEnd = rangeStart + Letter.decodedRangeLength[index] - 1
    val letterCode = Letter.decodedRangeCategory[index]

    if (code > rangeEnd) {
        return 0
    }

    val lastTwoBits = letterCode and 0x3

    if (lastTwoBits == 0) { // gap pattern
        var shift = 2
        var threshold = rangeStart
        for (i in 0..1) {
            threshold += (letterCode shr shift) and 0x7f
            if (threshold > code) {
                return 3
            }
            shift += 7
            threshold += (letterCode shr shift) and 0x7f
            if (threshold > code) {
                return 0
            }
            shift += 7
        }
        return 3
    }

    if (letterCode <= 0x7) {
        return lastTwoBits
    }

    val distance = (code - rangeStart)
    val shift = if (letterCode <= 0x1F) distance % 2 else distance
    return (letterCode shr (2 * shift)) and 0x3
}

